import { readFile, stat } from "node:fs/promises";
import { relative, resolve, sep } from "node:path";
import { parseApplicationDesignDocument, validateAuthoredApplicationDesignForm, } from "../engine/tooling/authored-application-design.js";
import { scanDesignMarkdown } from "../engine/tooling/markdown-design-source.js";
import { parseSimpleStateForm } from "../engine/tooling/simple-state-form.js";
import { validateSpecificationSignatureTypes, } from "../engine/tooling/specification-signature-types.js";
import { parseSpec } from "../engine/reactions/concepts/concept-spec.js";
import { specificationTypeNameEvidence } from "../engine/tooling/specification-type-evidence.js";
import { parseCommandOptions } from "./command-options.js";
import { diagnosticReport, failedDiagnostic, writeJsonDocument, } from "./diagnostic-report.js";
const usage = `sync-engine check-design <paths...> [--format json]
  Check explicit concept, composition, and application-types Markdown without loading configuration or application source.`;
function describe(error) {
    return error instanceof Error ? error.message : String(error);
}
function describeConceptSpecDiagnostics(source, diagnostics) {
    return diagnostics
        .map(({ code, message, location }) => `${source}:${location.line}:${location.column}: [${code}] ${message}`)
        .join("\n");
}
function describeSimpleStateFormIssues(issues) {
    return issues
        .map(({ code, message, suggestion, location }) => `${location.source}:${location.line}:${location.column}: [${code}] ${message}\n  suggestion: ${suggestion}`)
        .join("\n");
}
function conceptSpecDiagnostics(source, diagnostics) {
    return diagnostics.map(({ code, message, location }) => ({
        code,
        path: source,
        line: location.line,
        column: location.column,
        severity: "error",
        message,
    }));
}
function simpleStateFormDiagnostics(issues) {
    return issues.map(({ code, message, suggestion, severity, location }) => ({
        code,
        path: location.source,
        line: location.line,
        column: location.column,
        severity,
        message,
        suggestion,
    }));
}
function signatureTypeDiagnostics(source, issues) {
    return issues.map(({ code, message, suggestion, severity, location }) => ({
        code,
        path: source,
        line: location.line,
        column: location.column,
        severity,
        message,
        suggestion,
    }));
}
function applicationFormDiagnostic(issue) {
    return {
        code: issue.code,
        path: issue.location.source,
        line: issue.location.line,
        column: issue.location.column,
        severity: "error",
        message: issue.message,
    };
}
function invalidDocumentDiagnostic(source, error) {
    return {
        code: "DESIGN_DOCUMENT_INVALID",
        path: source,
        severity: "error",
        message: describe(error),
    };
}
function resemblesConcept(markdown, source) {
    try {
        const scanned = scanDesignMarkdown(markdown, source);
        const sectionNames = new Set(["Purpose", "Principle", "Types", "State", "Actions", "Queries"]);
        return (scanned.headings.filter(({ level, text }) => level === 2 && sectionNames.has(text)).length >=
            2);
    }
    catch {
        return false;
    }
}
async function inspectDesignFiles(paths, root) {
    const checked = [];
    const applicationDocuments = [];
    const failures = [];
    const diagnostics = [];
    const advice = [];
    for (const supplied of paths) {
        const absolute = resolve(root, supplied);
        const label = (relative(root, absolute) || supplied).split(sep).join("/");
        try {
            if (!(await stat(absolute)).isFile())
                throw new Error("path is not a regular file");
            const markdown = await readFile(absolute, "utf8");
            const parsed = parseSpec(markdown);
            if (parsed.specification !== undefined) {
                const stateFence = scanDesignMarkdown(markdown, label).fences.find(({ info }) => info === "state");
                if (stateFence === undefined)
                    throw new Error("parsed concept has no State fence");
                const parsedState = parseSimpleStateForm(stateFence, {
                    externalTypes: parsed.specification.externalTypes,
                    localTypes: parsed.specification.localTypes,
                    evidenceTypeNames: specificationTypeNameEvidence(parsed.specification),
                });
                const stateIssues = parsedState.issues;
                const stateErrors = stateIssues.filter(({ severity }) => severity === "error");
                // Advice explains why a name failed to resolve, so it is most useful beside an error.
                const stateAdvice = stateIssues.filter(({ severity }) => severity === "advice");
                if (stateAdvice.length > 0) {
                    advice.push(stateAdvice);
                    diagnostics.push(...simpleStateFormDiagnostics(stateAdvice));
                }
                if (stateErrors.length > 0) {
                    failures.push(`Design document ${label} is invalid: ${describeSimpleStateFormIssues(stateErrors)}`);
                    diagnostics.push(...simpleStateFormDiagnostics(stateErrors));
                    continue;
                }
                const signatureIssues = validateSpecificationSignatureTypes(parsed.specification, parsedState.document);
                if (signatureIssues.length > 0) {
                    failures.push(`Design document ${label} is invalid: ${signatureIssues
                        .map(({ code, message, suggestion, location }) => `${label}:${location.line}:${location.column}: [${code}] ${message}\n  suggestion: ${suggestion}`)
                        .join("\n")}`);
                    diagnostics.push(...signatureTypeDiagnostics(label, signatureIssues));
                    continue;
                }
                checked.push({ path: label, kind: "concept" });
                continue;
            }
            try {
                applicationDocuments.push(parseApplicationDesignDocument(markdown, label));
                checked.push({ path: label, kind: "application" });
            }
            catch (applicationError) {
                const conceptShaped = resemblesConcept(markdown, label);
                const detail = conceptShaped
                    ? describeConceptSpecDiagnostics(label, parsed.diagnostics)
                    : describe(applicationError);
                failures.push(`Design document ${label} is invalid: ${detail}`);
                diagnostics.push(...(conceptShaped
                    ? conceptSpecDiagnostics(label, parsed.diagnostics)
                    : [invalidDocumentDiagnostic(label, applicationError)]));
            }
        }
        catch (error) {
            failures.push(`Design document ${label} is invalid: ${describe(error)}`);
            diagnostics.push(invalidDocumentDiagnostic(label, error));
        }
    }
    for (const issue of validateAuthoredApplicationDesignForm(applicationDocuments)) {
        failures.push(`Design document ${issue.location.source} is invalid: ${issue.location.source}:${issue.location.line}:${issue.location.column}: [${issue.code}] ${issue.message}`);
        diagnostics.push(applicationFormDiagnostic(issue));
    }
    return { checked, failures, diagnostics, advice };
}
function printStateAdvice(advice) {
    for (const issues of advice)
        console.warn(describeSimpleStateFormIssues(issues));
}
function throwDesignFailures(failures) {
    if (failures.length > 0)
        throw new Error(failures.join("\n"));
}
/** Check explicit authored-design files without consulting an assembly or project state. */
export async function checkDesignFiles(paths, root = process.cwd()) {
    const outcome = await inspectDesignFiles(paths, root);
    printStateAdvice(outcome.advice);
    throwDesignFailures(outcome.failures);
    return outcome.checked;
}
export async function checkDesignCommand(args, render = "text") {
    const options = parseCommandOptions(args, usage, { format: true, operands: "required" });
    const output = render === "silent" ? "silent" : options.format;
    let outcome;
    try {
        outcome = await inspectDesignFiles(options.operands, process.cwd());
    }
    catch (error) {
        if (output !== "json")
            throw error;
        const report = diagnosticReport("check-design", "failed", [
            failedDiagnostic("CHECK_DESIGN_FAILURE", error),
        ]);
        writeJsonDocument(report);
        return report;
    }
    const report = diagnosticReport("check-design", outcome.failures.length === 0 ? "passed" : "failed", outcome.diagnostics);
    if (output === "json") {
        writeJsonDocument(report);
        return report;
    }
    if (output === "text")
        printStateAdvice(outcome.advice);
    throwDesignFailures(outcome.failures);
    if (output === "text") {
        console.log(`Design form check passed for ${outcome.checked.length} file${outcome.checked.length === 1 ? "" : "s"}.`);
    }
    return report;
}
